(1, 'Laptops & Computers', 'laptops-computers', 'High performance laptops, ultra-books, and workstation desktops for coding, gaming, and creative work.', 'https://images.unsplash.com/photo-1496181133206-80ce9b88a853?auto=format&fit=crop&w=800&q=80'),
(2, 'Audio & Headphones', 'audio-headphones', 'Studio grade wireless earbuds, noise-cancelling headphones, and soundbars.', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=800&q=80'),
(3, 'Smartphones & Wearables', 'smartphones-wearables', 'Next-generation flagship smartphones, smartwatches, and fitness trackers.', 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=800&q=80'),
(4, 'Fitness & Sports', 'fitness-sports', 'Marathon running shoes, athletic apparel, gym gear, and recovery equipment.', 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=800&q=80'),
